    counters = []
    sizes = []

    for _ in range(n):
        k = int(data[idx])
        idx += 1

        c = Counter()
        for _ in range(k):
            c[int(data[idx])] += 1
            idx += 1

        counters.append(c)
        sizes.append(k)

    ans = 0.0

    for i in range(n):
        for j in range(i + 1, n):
            ci, cj = counters[i], counters[j]
            if len(ci) > len(cj):
                ci, cj = cj, ci

            same = 0
